# Hotkeys button-dropdown rail colors are keyed on the chord-button REGION
# (keybinds_runtime.CHORD_BUTTON_GROUP) rather than on the label text  see
# _CHORD_GROUP_COLORS, defined with the rest of the palette below.

# Key-capture widget: Tk keysym → modifier token / runtime token.
_KC_MOD_KEYSYM = {
    "Control_L": "ctrl", "Control_R": "ctrl",
    "Alt_L": "alt",     "Alt_R": "alt",
    "Shift_L": "shift", "Shift_R": "shift",
    "Win_L": "win",     "Win_R": "win",
    "Super_L": "win",   "Super_R": "win",
    "Meta_L": "win",    "Meta_R": "win",
}
_KC_KEYSYM_TOKEN = {
    "Return": "enter",  "BackSpace": "backspace", "Delete": "delete",
    "Tab": "tab",       "space": "space",
    "Prior": "pageup",  "Next": "pagedown",
    "Home": "home",     "End": "end",    "Insert": "insert",
    "Left": "left",     "Right": "right", "Up": "up", "Down": "down",
    "F1": "f1", "F2": "f2", "F3": "f3",  "F4": "f4",
    "F5": "f5", "F6": "f6", "F7": "f7",  "F8": "f8",
    "F9": "f9", "F10": "f10", "F11": "f11", "F12": "f12",
    # Numpad, NumLock on…
    "KP_Add": "kp_plus", "KP_Subtract": "kp_minus",
    "KP_Multiply": "kp_multiply", "KP_Divide": "kp_divide",
    "KP_Decimal": "kp_period", "KP_Enter": "kp_enter",
    # …and off (the nav cluster the same physical keys become).
    "KP_Home": "home", "KP_End": "end", "KP_Prior": "pageup",
    "KP_Next": "pagedown", "KP_Insert": "insert", "KP_Delete": "delete",
    "KP_Left": "left", "KP_Right": "right", "KP_Up": "up", "KP_Down": "down",
}
_KC_KEYSYM_TOKEN.update({"KP_%d" % _n: "kp_%d" % _n for _n in range(10)})
_KC_IGNORE_KEYSYM = frozenset(_KC_MOD_KEYSYM) | {
    "Caps_Lock", "Num_Lock", "Scroll_Lock",
}
_KC_MOD_ORDER = ("ctrl", "shift", "alt", "win")


def _make_key_capture_entry(parent, var, bg, fg, width=24):
    """A tk.Entry that captures live key combos instead of typed text.
    Click the field and press keys  modifiers show live ('Ctrl + Alt + …'),
    releasing the final key locks in the combo. Backspace clears the field;
    clicking away during partial capture restores the previous value."""
    _s = {"on": False, "mods": set(), "prev": ""}

    ent = tk.Entry(parent, textvariable=var, bg=bg, fg=fg,
                   insertbackground=fg, relief="flat", width=width)

    def _cancel(evt=None):
        if not _s["on"]:
            return
        _s["on"] = False
        _s["mods"] = set()
        var.set(_s["prev"])

    def _finish(keys):
        _s["on"] = False
        _s["mods"] = set()
        var.set(keybinds_runtime.chord_keys_label(keys) if keys else "")

    def _live():
        ordered = [m for m in _KC_MOD_ORDER if m in _s["mods"]]
        var.set(keybinds_runtime.chord_keys_label(ordered + ["…"])
                if ordered else "Press keys…")

    def _on_press(evt):
        ks = evt.keysym
        # Backspace (no mods held) = clear the saved combo
        if ks == "BackSpace" and not _s["mods"]:
            _s["on"] = False
            _s["mods"] = set()
            var.set("")
            return "break"
        # Escape = cancel any in-progress capture (restores prev)
        if ks == "Escape":
            _cancel()
            return "break"
        # Modifier key: enter capture mode on first one, accumulate
        if ks in _KC_MOD_KEYSYM:
            if not _s["on"]:
                _s.update(on=True, mods=set(), prev=var.get())
            _s["mods"].add(_KC_MOD_KEYSYM[ks])
            _live()
            return "break"
        if ks in _KC_IGNORE_KEYSYM:
            return "break"
        # Non-modifier key = finalise combo (with whatever mods are held)
        tok = _KC_KEYSYM_TOKEN.get(ks)
        if tok is None:
            if len(ks) == 1:
                tok = ks.lower()
            elif ks.startswith("F") and ks[1:].isdigit():
                tok = ks.lower()
        if tok is None:
            return "break"
        mods_held = [m for m in _KC_MOD_ORDER if m in _s["mods"]]
        _finish(mods_held + [tok])
        return "break"

    def _on_release(evt):
        if not _s["on"]:
            return "break"
        ks = evt.keysym
        if ks in _KC_MOD_KEYSYM:
            _s["mods"].discard(_KC_MOD_KEYSYM[ks])
            _live()
        return "break"

    ent.bind("<FocusOut>", _cancel, add="+")
    ent.bind("<KeyPress>", _on_press, add="+")
    ent.bind("<KeyRelease>", _on_release, add="+")
    return ent


def _normalize_chords(chords):
    """Accept the per-controller dict {"sc":[...],"switch":[...]} or the legacy
    FLAT list (treated as the SC list); return a full {kind: list} map."""
    if isinstance(chords, dict):
        return {k: list(chords.get(k) or []) for k in _KINDS}
    return {"sc": list(chords or []), "switch": []}

# --- Palette (Steam-ish dark) ----------------------------------------------
_BG = "#0e141b"          # window background
_PANEL = "#1b2838"       # raised panels / header
_ENTRY = "#2a475e"       # combobox field
_ENTRY_HI = "#335b7a"
_FG = "#ced0d2"          # primary text (RGB 206,208,210)
_GREEN = "#5fd75f"       # Gamepad Layout dropdown rail (all options there are
                         # actual gamepad-controller binds, so they're greened
                         # to read as distinct from keyboard/mouse actions)
# Category-tag colors picked to sit apart around the wheel from _GREEN (120°)
# and _ACCENT (202°), so all four read as one cohesive "tag" family against
# the dark UI instead of clashing.
#
# _ORANGE/_PINK went through two passes: full-pastel neon (S~78%/L~75%) was
# the original "pops too hard" version; pulling BOTH down to the same flat
# S~45%/L~65% fixed the popping but overcorrected  orange and pink landed so
# close in lightness/saturation to each other AND to _MODIFIER's grey that
# they got hard to tell apart at a 20px rail glance. This pass keeps them
# desaturated relative to the original neon, but gives them room to be told
# apart: different saturation targets per hue (gold reads clearly at higher S
# than magenta needs to) and enough lightness gap from _MODIFIER (#c0c3c8,
# L~78%) that "grey" isn't a third color fighting for the same visual slot.
_ORANGE = "#d6ae51"      # non-keyboard system/media actions  warm gold
                         # (~42°, S~62%/L~58%), near the complement of
                         # _ACCENT's blue
_PURPLE = "#b98cf2"      # Guide/View/Menu/QAM meta buttons (~267°)
_PINK = "#d16190"        # mouse actions  click/wheel/pointer-mode options 
                         # rose/berry (~335°, S~55%/L~60%), far enough from
                         # _ORANGE's hue and _PURPLE's lightness to read as
                         # its own color rather than a shade of either
_MODIFIER = "#c0c3c8"    # modifier and special keys (Shift/Ctrl/Alt/Win,
                         # arrows, Enter, Tab, etc.)  a cooler white shade to
                         # distinguish from regular letter/number keys
_TEAL = "#5ec9b8"        # trackpad / touch-surface controls in the Hotkeys
                         # button dropdown (~170°, S~50%/L~58%). Sits in the
                         # one wide gap left on the wheel  between _GREEN
                         # (120°) and _ACCENT (202°)  so the eight chord-button
                         # regions each get a rail hue that's tellable apart at
                         # a 20px glance. Cyan-leaning enough not to read as a
                         # shade of _GREEN's pure green.
# Dropdown label text is ALWAYS this, whatever category the value belongs to.
# The four hues above are worn by a solid rail down the field's left edge
# instead (_Dropdown._rail_for / _paint_rail): a fixed-position mark keeps
# the same at-a-glance grouping the colored text gave, without tinting body
# copy. Just the _DD_RAIL_W bar, no fade-out taper into the surface  that
# was tried and dropped, since it ate ~20px of extra gutter before the text
# on every Gamepad/Chords/Desktop dropdown. Text sits _DD_RAIL_W + a small
# gap after the bar (see _redraw's `tx`, the flat popup's `rtx`, and
# _gp_paint_cell's `tx`); rail-less dropdowns use _DD_TEXT_PAD instead.
_DD_TEXT = "#f4f6f8"
_DD_RAIL_W = 7           # solid color bar width
_DD_RAIL_HI = 0.34       # how far the leading edge lightens toward white
_DD_RAIL_HI_MIN = 40     # ...floored to at least this much per channel, so a
                         # pale color (_MODIFIER) still gets a visible
                         # highlight instead of an imperceptibly flat rail
_DD_RAIL_GAP = 4         # bar -> text gap
# Dropdowns with no value_color_fn (Options pages, Skin picker, etc.) never
# paint a rail, so they use this plain left pad instead of _DD_RAIL_W +
# _DD_RAIL_GAP.
_DD_TEXT_PAD = 12
_MUTED = "#8b929a"       # section headers / hints
_ACCENT = "#66c0f4"      # Steam light blue (button glyph chips)
_RESET_BTN_BG = "#44464D"   # Reset Settings > Reset to Default (RGB 68,70,77)
_RESET_BTN_FG = "#E8EAED"   # its label text (RGB 232,234,237)
_OUTLINE = "#aeb6bd"     # controller line-art
_PANEL_BOX = "#23262e"   # grey card behind each Desktop-Settings panel
_DROPDOWN = "#6f7378"    # (legacy light dropdown field  Panel.TCombobox style)
_DROPDOWN_FIELD = "#44464d"  # closed dropdown + selected top row (RGB 68,70,77)
_DROPDOWN_OPT = "#23262e"    # dropped-down option rows (the prior field color)
_DROPDOWN_HOVER = "#2e3138"  # option row hover
_DD_HOVER = "#4f5158"        # closed-field hover (RGB 79,81,88), fades in/out
_DD_FLASH = "#393f49"        # closed-field/gear click flash (RGB 57,63,73)
_TOGGLE_OUTLINE = "#65686d"  # toggle hover outline (RGB 101,104,109), 4px AA
_GEAR_BG = "#44464d"     # gear / settings button
_PANEL_RADIUS = 1        # corner rounding (px) for Desktop-Settings panels

# -- Hotkeys button-dropdown rail colors --------------------------------------
# One hue per PHYSICAL REGION of the controller. Region keys and membership live
# in keybinds_runtime.CHORD_BUTTON_GROUP, which also fixes the dropdown ORDER 
# so each dropdown reads as coloured blocks: find the region, then the button.
#
# This used to be label-driven and only ever painted two of the eight: the SC's
# literal "Guide"/"View"/"Menu"/"QAM" strings, and the xi_ output names. Every
# other row fell through to no rail  and on a non-SC pad that was EVERY row,
# since a Switch prints its meta buttons "–"/"+"/"⌂" and matched nothing. Keying
# on the control id instead lets a kind's labels be whatever the hardware says
# while the colors still land.
_CHORD_GROUP_COLORS = {
    "meta":     _PURPLE,    # Guide / View / Menu / QAM / Minus / Plus / Capture
    "face":     _ACCENT,    # A B X Y
    "shoulder": _ORANGE,    # bumpers + triggers
    "paddle":   _PINK,      # rear paddles + grip-rest sensors
    "stick":    _MODIFIER,  # stick clicks + capacitive stick touch
    "dpad":     _MODIFIER,  # dpad  shares the sticks' grey (both directional)
    "pad":      _TEAL,      # trackpad click/touch, PlayStation touchpad click
    "output":   _GREEN,     # xi_ Gamepad-Layout aliases (Gamepad Mode only)
}

# kind -> {dropdown label: rail color}. Per kind, because a kind's labels are
# its own printed names and the same text can mean different regions on
# different pads. "None" is absent on purpose  that row stays unrailed.
_CHORD_BTN_COLORS = {
    k: {lbl: _CHORD_GROUP_COLORS[keybinds_runtime.chord_button_group(cid)]
        for cid, lbl in src}
    for k, src in _CHORD_BTN_SRC.items()
}


def _chord_color_fn(kind):
    """value_color_fn for `kind`'s chord-button dropdowns: label -> rail color
    (None for the "None" row)."""
    return _CHORD_BTN_COLORS[kind].get


def _chord_label_group(kind, label):
    """Region key behind a chord-dropdown label on this kind, or None."""
    cid = _CHORD_LBL2ID.get(kind, {}).get(label)
    return keybinds_runtime.chord_button_group(cid) if cid else None


# Caption + order for the chord dropdowns' section headings. The vocabulary is
# ALREADY emitted region by region (see SC_CHORD_BUTTON_LABELS) and the rail
# colours already encode the same regions  the captions only say out loud what
# that colour column has been implying, so nothing is reordered.
_CHORD_GROUP_TITLES = [
    ("meta", "System"), ("face", "Face Buttons"),
    ("shoulder", "Shoulders & Triggers"), ("paddle", "Grips & Paddles"),
    ("stick", "Stick Clicks"), ("dpad", "D-Pad"), ("pad", "Trackpads"),
    ("output", "Gamepad Output"),
]


def _chord_sections(kind, labels):
    """[(caption, [label, ...])] for one kind's chord-button dropdown. "None"
    leads, uncaptioned; a region this pad hasn't got simply doesn't appear."""
    buckets = {}
    for lbl in labels:
        g = _chord_label_group(kind, lbl)
        if g:
            buckets.setdefault(g, []).append(lbl)
    out = [("", ["None"])] if "None" in labels else []
    for key, title in _CHORD_GROUP_TITLES:
        if buckets.get(key):
            out.append((title, buckets[key]))
    return out


# -- dependency connectors ("group rail") -------------------------------------
# Options pages where one control gates several others (Sleep Manager's master
# toggle -> Sleep Mode -> the two timeout sliders) draw a file-tree style rail
# down the left gutter: each dependent card is indented one level and an elbow
# links it to the control it hangs off. The rail dims together with the cards
# it feeds, so "why is this greyed out?" is answerable by following the line
# up to the switch that turns it back on. See _panel_card(indent=, tree=).
_RAIL_INDENT = 26        # px a card shifts right per nesting level
_RAIL_GAP = 6            # inter-card gap, baked into a rail card's canvas so
                         # the connector line is unbroken between cards
_RAIL_W = 2              # connector line thickness
_RAIL_FG = "#4c5665"     # connector color while the group is live
_RAIL_FG_DIM = "#262b33" # connector color while the group is greyed out

# -- controller-driven UI navigation ------------------------------------------
# The picker is steerable with the Steam Controller while it is visible AND
# foreground: dpad moves a highlight, A activates, B backs out, L1/R1 cycle
# the Desktop/Chords/Gamepad/Controller/Options tabs. Frames arrive through sc_viewer's
# publish slot (same channel as the live viewer); the tray masks these bits
# out of its own dispatch while the picker claims them (sc_viewer.set_nav).
_NAV_HL = "#383a41"      # highlighted card/row bg  user-specified RGB 56,58,65
_NAV_RING = "#1a9fff"    # focused layout-row outline ring (accent blue)
# Button bits (== steamcontroller.SCButtons, inlined like sc_viewer's).
_NB_A, _NB_B = 0x1, 0x2
_NB_X, _NB_Y = 0x4, 0x8
_NB_RB = 0x200
_NB_DDOWN, _NB_DRIGHT, _NB_DLEFT, _NB_DUP = 0x400, 0x800, 0x1000, 0x2000
_NB_START = 0x4000        # Menu / Options / "+" / ≡  the "hamburger" button
_NB_LB = 0x80000
_NAV_DIR_BITS = (_NB_DUP, _NB_DDOWN, _NB_DLEFT, _NB_DRIGHT)
_NAV_BITS = _NAV_DIR_BITS + (_NB_A, _NB_B, _NB_X, _NB_Y, _NB_START,
                             _NB_LB, _NB_RB)
# Steam/Home (0x10000) and "..."/QAM (0x10). Navigation is a BARE-button
# vocabulary: while either is held the frame is a CHORD the tray dispatches
# (Steam+X opens the on-screen keyboard, Steam+dpad is media, ...), so the nav
# pump swallows it  otherwise Steam+X both opened the OSK and reset the
# highlighted row. Mirrors the tray's own _GUIDE_BITS exemption.
_NAV_GUIDE_BITS = 0x10000 | 0x10
_NAV_REPEAT_DELAY = 0.40   # held dpad: first auto-repeat after this
_NAV_REPEAT_EVERY = 0.12   # ...then this fast
_NAV_SLIDER_STEP_PCT = 5   # slider-control mode: one dpad tap = 5%
_NAV_SLIDER_FINE_PCT = 1   # ...in fine-adjust mode (Y toggles): 1%
# Touch SENSOR bits (pad/stick touch, grip rest)  never a capturable "press"
# for the Listen bind mode (they'd fire the instant a thumb rests anywhere).
_NAV_TOUCH_BITS = (0x100000 | 0x200000 | 0x1000000 | 0x2000000
                   | 0x10000000 | 0x20000000)
# Keyboard mirror of the controller navigation: each key press is translated to
# the SAME _NB_* button bit the Steam Controller would emit and fed through the
# exact _nav_press dispatch, so the whole picker is steerable with the keyboard
# identically to the pad. Tab/Shift-Tab are handled separately (they need the
# Shift state) but do the same job as PageDown/PageUp (L1/R1 tab cycling).
#   arrows      -> dpad          Enter / Space -> A (Select / Activate)
#   Escape      -> B (Back)      Delete        -> X (Remove Command / Reset)
#   PageUp/Down -> L1/R1 tabs    F2            -> Menu/≡ (Enter Value / Listen)
#   F3          -> Y (fine-adjust toggle on a captured slider)
_KBD_NAV_MAP = {
    "Up": _NB_DUP, "Down": _NB_DDOWN, "Left": _NB_DLEFT, "Right": _NB_DRIGHT,
    "Return": _NB_A, "KP_Enter": _NB_A, "space": _NB_A,
    "Escape": _NB_B,
    "Prior": _NB_LB, "Next": _NB_RB,          # PageUp / PageDown
    "Delete": _NB_X, "KP_Delete": _NB_X,
    "F2": _NB_START,
    "F3": _NB_Y,
}
# Focused-widget classes that own the keyboard themselves  while one of these
# holds focus the keyboard is NOT hijacked for navigation: text fields let the
# caret/commit/cancel keys through, and a ttk combobox popdown Listbox keeps its
# stock Up/Down/Return/Escape selection bindings + our type-ahead.
_KBD_TEXT_CLASSES = frozenset(("Entry", "TEntry", "Text", "Spinbox", "TSpinbox"))
# SCButtons attribute name -> bit, for mapping a Listen-captured press onto
# the chord-button vocabularies (keybinds_runtime.chord_buttons_for names
# buttons by SCButtons attr). Inlined like the _NB_* bits above.
_SCB_NAME_TO_BIT = {
    "A": 0x1, "B": 0x2, "X": 0x4, "Y": 0x8, "QAM": 0x10, "R3": 0x20,
    "VIEW": 0x40, "RGRIP1": 0x80, "RGRIP2": 0x100, "RB": 0x200,
    "DPAD_DOWN": 0x400, "DPAD_RIGHT": 0x800, "DPAD_LEFT": 0x1000,
    "DPAD_UP": 0x2000, "START": 0x4000, "L3": 0x8000, "STEAM": 0x10000,
    "LGRIP1": 0x20000, "LGRIP2": 0x40000, "LB": 0x80000,
    "RPADJOY_TOUCH": 0x100000, "RPADTOUCH": 0x200000, "RPAD": 0x400000,
    "RT": 0x800000, "LPADJOY_TOUCH": 0x1000000, "LPADTOUCH": 0x2000000,
    "LPAD": 0x4000000, "LT": 0x8000000,
    "RGRIP_REST": 0x10000000, "LGRIP_REST": 0x20000000,
}
# Physical button bit -> Gamepad-tab (XInput output) action id, for the Listen
# bind mode on Gamepad Layout rows: press the physical button that produces an
# output BY DEFAULT and the focused row binds that output.
_NAV_BIT_TO_XOUT = {
    0x1: "btn_a", 0x2: "btn_b", 0x4: "btn_x", 0x8: "btn_y",
    0x80000: "lb", 0x200: "rb", 0x8000000: "lt", 0x800000: "rt",
    0x8000: "ls", 0x20: "rs", 0x40: "back", 0x4000: "start", 0x10000: "guide",
    0x2000: "dpad_up", 0x400: "dpad_down", 0x1000: "dpad_left",
    0x800: "dpad_right",
}
# Per-kind: button bit -> chord-button dropdown id (Hotkeys "Button A/B",
# Gamepad-Mode toggle bars). Built from the runtime's own id->SCButtons-attr
# map so the two can't drift; xi_ output aliases are skipped (a physical press
# should capture the physical name) and the Guide/Home bit maps to the
# vocabulary's Guide entry.
def _bit_to_chord_id(kind):
    out = {}
    for cid, attr in keybinds_runtime.chord_buttons_for(kind).items():
        bit = _SCB_NAME_TO_BIT.get(attr)
        if bit is None or cid.startswith("xi_"):
            continue
        out.setdefault(bit, cid)
    out.setdefault(_SCB_NAME_TO_BIT["STEAM"], keybinds_runtime.CHORD_GUIDE_ID)
    return out

# Controller kinds whose tabs/pages this picker instance builds. The full
# catalog lives in pads.py; only UNLOCKED kinds are built (the Steam Controller
# always, plus every kind the tray has ever detected  see
# settings["seen_controllers"]). Set by _Picker.__init__ from the general
# settings BEFORE any layout is built; the ("sc", "switch") default keeps the
# standalone `python keybinds_picker.py` harness working.
_KINDS = ("sc", "switch")
# "guide" = the Chords tab: actions fired when the Guide button (Steam / "..." on
# the SC, Home on a Switch Pro) is HELD and another control is pressed.
_MODES = ("pc", "gamepad", "guide")
# How many profile slots a single (controller, layout tab) may hold  the footer
# "+" stops here and every stored slot number is clamped to it. Kept as ONE
# constant because the same ceiling is enforced in three places that must agree:
# the slot storage built in __init__, the footer "+", and the tray's settings
# migration (tray._MAX_KEYBIND_PROFILES mirrors this value).
_MAX_PROFILES = 10
# Longest profile NAME the footer's name box accepts. Long enough for a
# "Left-Handed" / "Photoshop" style label, short enough that the box can never
# push the numbered slot buttons off a squeezed footer.
_NAME_MAX = 24


def _set_unlocked_kinds(seen):
    """Set the module-wide kind list for the picker being built, and rebuild
    the category list to match (one Controller-tab category per unlocked
    controller, appended after the base categories in catalog order)."""
    global _KINDS, _SETTINGS_CATEGORIES, _CAT_KIND
    _KINDS = pads.unlocked_kinds(seen)
    _CAT_KIND = {pads.display_name(k): k for k in _KINDS}
    _SETTINGS_CATEGORIES = list(_BASE_CATEGORIES) + list(_CAT_KIND)

# The windowed size of the manager. PINNED, not merely initial: the user can
# drag the window to any size, but that size is never remembered  every
# restore (out of the taskbar, or out of maximized) snaps it straight back to
# these numbers, which is the one geometry the whole UI is laid out around.
# See _pin_windowed_size.
#
# It is the DESIGN size, not a promise: every geometry goes through
# _fit_win_size, which shrinks it to whatever the monitor's work area can
# actually hold. 850 + the title bar + a taskbar overflows a 1600x900 screen by
# ~30px, and an oversized window hangs its BOTTOM off the desktop  which is
# where the footer (Restore Defaults / Profile slots / Save) and the layout
# tabs' bottom dropdown row live. See also _layout_fit, which shrinks the
# controller art by the same deficit so the page inside fits too.
_WIN_W = 1242
_WIN_H = 850


def _work_area_size():
    """(w, h) of the primary monitor's USABLE desktop  the whole screen minus
    the taskbar. None when it can't be queried (non-Windows, or the API fails).

    The user32 handle is a private WinDLL instance, never ctypes.windll.user32:
    argtypes stamped on the shared one leak between call sites (see
    _ghost_user32)."""
    if sys.platform != "win32":
        return None
    try:
        class _RECT(ctypes.Structure):
            _fields_ = [("left", ctypes.c_long), ("top", ctypes.c_long),
                        ("right", ctypes.c_long), ("bottom", ctypes.c_long)]

        u = ctypes.WinDLL("user32")
        spi = u.SystemParametersInfoW
        spi.restype = ctypes.c_int
        spi.argtypes = [ctypes.c_uint, ctypes.c_uint, ctypes.c_void_p,
                        ctypes.c_uint]
        r = _RECT()
        if not spi(0x0030, 0, ctypes.byref(r), 0):      # SPI_GETWORKAREA
            return None
        w, h = r.right - r.left, r.bottom - r.top
        if w <= 0 or h <= 0:
            return None
        return (w, h)
    except Exception:
        return None


def _frame_size():
    """(w, h) the OS window frame adds AROUND the client area  caption plus
    both sizing borders. Tk's geometry is client-area only, so this is what
    the work-area fit has to allow for on top of it."""
    if sys.platform != "win32":
        return (0, 40)          # X11/Wayland: one titlebar's worth, near enough
    try:
        u = ctypes.WinDLL("user32")
        gm = u.GetSystemMetrics
        gm.restype = ctypes.c_int
        gm.argtypes = [ctypes.c_int]
        cap = gm(4)             # SM_CYCAPTION
        fx, fy = gm(32), gm(33)  # SM_CXSIZEFRAME / SM_CYSIZEFRAME
        pad = gm(92)            # SM_CXPADDEDBORDER
        return (2 * (fx + pad), cap + 2 * (fy + pad))
    except Exception:
        return (16, 40)


def _fit_win_size(root=None):
    """The windowed size to actually use: the design size above, clamped so the
    whole window  frame included  fits the primary monitor's work area.

    Re-queried on every pin rather than cached: resolution changes, a taskbar
    moving, and docking/undocking all move the work area under a running
    picker. The floors stop a pathological work area (a sliver of a monitor
    reported mid-mode-switch) from collapsing the window to nothing."""
    fw, fh = _frame_size()
    wa = _work_area_size()
    if wa is None and root is not None:
        try:
            wa = (root.winfo_screenwidth(), root.winfo_screenheight() - 64)
        except tk.TclError:
            wa = None
    if not wa:
        return (_WIN_W, _WIN_H)
    return (max(900, min(_WIN_W, wa[0] - fw)),
            max(560, min(_WIN_H, wa[1] - fh)))

# The Controller/Options tabs' shared left category panel (256 wide, RGB
# 43,45,51), rows of 42px.
# The selected row is backed by category_selected.png (254x42).
_CAT_PANEL_W     = 256   # windowed panel width
_CAT_PANEL_W_MAX = 331   # maximized / fullscreen panel width
_CAT_ROW_H = 42
_CAT_PANEL_BG = "#2b2d33"
_CAT_HOVER_BG  = "#35373d"   # RGB 53,55,61  row hover highlight
_CAT_ACCENT    = "#1a9fff"   # RGB 26,159,255  selected-row left accent bar
_CAT_ACCENT_NAV = "#5aa9d6"  # accent bar while controller dpad focus is on the category selector
# Virtual Menus live preview (pinned to the sidebar bottom while the
# "Virtual Menus" category is open).
_VMENU_PREVIEW_W = 236
_VMENU_PREVIEW_H = 208
# TWO sidebar-driven tabs share all of the machinery below  "Controller"
# (everything that shapes how a pad behaves) and "Options" (the app's own
# settings). A category name belongs to exactly ONE of them, which is what
# _cat_view reads back, so every cat-keyed registry in the picker stays flat
# (one namespace, no (view, cat) tuples) even though the pages live on two
# different tabs.
_SETTINGS_VIEWS = ("controller", "settings")
# Options tab  app- and system-wide pages.
_OPTIONS_CATEGORIES = ["Keyboard", "Gamepad Mode", "General", "Steam",
                       "Big Picture", "Windows", "Sleep Manager"]
# Controller tab  the per-pad pages. "Trackpads" is offered only on the kinds
# that HAVE trackpads (both Steam Controllers + the Deck  pads.HID_KINDS);
# each unlocked controller also gets its OWN page, appended after these by
# _set_unlocked_kinds (which also builds the name→kind map).
_CONTROLLER_CATEGORIES = ["Advanced Presses", "Trackpads",
                          "Virtual Menus", "Gyro"]
_ADV_CAT = "Advanced Presses"
# "Gyro"  ONE page for every controller's gyro settings (it used to be a
# cog-wheel modal on each controller's own page). Which controller it edits is
# picked by the dropdown at the top of the page, so the page exists once per
# tab rather than once per pad, and is hidden outright when no unlocked
# controller has a gyroscope.
_GYRO_CAT = "Gyro"
# The old standalone "Hotkeys" category  merged into the Advanced Presses
# page (its chord rows render there as Hotkey pipelines now). The name is kept
# only so stale references (remembered category selections, nav-zone guards)
# stay harmless; it is no longer in _CONTROLLER_CATEGORIES.
_HOTKEYS_CAT = "Hotkeys"
_TRACKPADS_CAT = "Trackpads"
_BASE_CATEGORIES = _OPTIONS_CATEGORIES + _CONTROLLER_CATEGORIES
# Purely visual breaks in the sidebar (no effect on nav order/indices, which
# stay driven by the view's own category list)  they split each list into
# groups to cut clutter. On Options that's the INPUT pages then the APP/SYSTEM
# ones; on Controller the per-pad pages are already separated by the rule drawn
# before the first per-controller row. See _cat_separator for the rule itself.
_CAT_GAP_AFTER = {"settings": "Gamepad Mode", "controller": None}
_CAT_GAP_H = 27          # height of the blank strip the rule sits in
_CAT_RULE_INSET = 22     # px the rule stays clear of the panel's side edges
_CAT_RULE_COLOR = "#727888"   # rule color across its full-strength middle
# Fraction of each half-span held at FULL strength before the tips start to
# fade. A pure falloff-from-centre dimmed most of the rule (barely visible);
# a plateau keeps it a crisp line that only melts at the very ends.
_CAT_RULE_PLATEAU = 0.62
_CAT_KIND = {pads.display_name(k): k for k in _KINDS}
_SETTINGS_CATEGORIES = list(_BASE_CATEGORIES) + list(_CAT_KIND)


def _cat_view(cat):
    """Which tab a category's page lives on  "controller" or "settings".
    Category names are unique across the two, so this is the single place that
    decides, and every other cat-keyed lookup can stay view-agnostic."""
    return ("controller" if cat in _CONTROLLER_CATEGORIES or cat in _CAT_KIND
            else "settings")


def _gyro_kinds():
    """Unlocked controllers with a gyroscope  the "Gyro" page's dropdown, and
    whether that page is offered at all."""
    return [k for k in _KINDS if pads.has_gyro(k)]


def _view_cats(view, kind):
    """The sidebar list for one tab, for the controller it is showing. Only the
    Controller tab varies by kind: "Trackpads" is dropped on a pad that hasn't
    got any. "Gyro" covers every controller from one page, so it drops out only
    when NO unlocked pad has a gyroscope."""
    if view != "controller":
        return list(_OPTIONS_CATEGORIES)
    return [c for c in _CONTROLLER_CATEGORIES
            if (c != _TRACKPADS_CAT or kind in pads.HID_KINDS)
            and (c != _GYRO_CAT or _gyro_kinds())] + list(_CAT_KIND)


def _view_label(view):
    """The tab's own name, for cross-references written into hint text."""
    return "Controller" if view == "controller" else "Options"

